"""Breeze generation through LocalAI, per passage and method."""

import functools
import io
import json
import re
import subprocess
import tempfile
import time
from dataclasses import asdict
from pathlib import Path
from typing import Callable

import httpx
import numpy as np
import soundfile as sf

from . import audio
from .chapter import Passage
from .config import BREEZE_URL, CONTAINER_VOICES, FALLBACK_REF, MAX_CHARS, SAMPLE_RATE, TARGET_DBFS
from .library import RefClip, pick
from .names import apply_names
from .textunits import chunk

METHODS = ["current", "matched", "matched_names"]
ATTEMPTS = 3
GAP_S = 0.12

Synth = Callable[[str, str, str], np.ndarray]


class TTSFailed(Exception):
    pass


def speak(text: str, ref_file: str, ref_text: str, client: httpx.Client | None = None,
          backoff_s: float = 5.0, temperature: float | None = None) -> np.ndarray:
    client = client or httpx.Client(timeout=300)
    body = {
        "model": "breeze-tts-2",
        "input": text,
        "voice": f"{CONTAINER_VOICES}/{ref_file}",
        "params": {"reference_text": ref_text, "seed": "42", "text_chunk_size": "2000"},
    }
    if temperature is not None:
        body["params"]["temperature"] = str(temperature)
    error = "no attempt"
    for attempt in range(ATTEMPTS):
        try:
            resp = client.post(BREEZE_URL, json=body)
            if resp.status_code == 200:
                samples, rate = sf.read(io.BytesIO(resp.content), dtype="float64", always_2d=False)
                if rate != SAMPLE_RATE:
                    raise TTSFailed(f"unexpected sample rate {rate}")
                return samples
            error = f"HTTP {resp.status_code}: {resp.text[:200]}"
        except httpx.HTTPError as exc:
            error = f"{type(exc).__name__}: {exc}"
        time.sleep(backoff_s * (attempt + 1))
    raise TTSFailed(error)


def render(text: str, ref_file: str, ref_text: str, client: httpx.Client | None = None,
           temperature: float | None = None) -> np.ndarray:
    client = client or httpx.Client(timeout=300)
    gap = np.zeros(int(SAMPLE_RATE * GAP_S))
    parts: list[np.ndarray] = []
    for piece in chunk(text, MAX_CHARS):
        if parts:
            parts.append(gap)
        parts.append(audio.level(speak(piece, ref_file, ref_text, client, temperature=temperature), TARGET_DBFS))
    return np.concatenate(parts) if parts else np.zeros(0)


def encode_opus(samples: np.ndarray, out: Path) -> Path:
    with tempfile.NamedTemporaryFile(suffix=".wav") as tmp:
        audio.write(Path(tmp.name), samples, SAMPLE_RATE)
        subprocess.run(["ffmpeg", "-v", "error", "-y", "-i", tmp.name, "-c:a", "libopus", "-b:a", "48k", str(out)],
                       check=True)
    return out


def _fresh(out: Path, signature: dict) -> bool:
    """The output exists and was made from exactly this text and reference clip."""
    sidecar = out.with_suffix(".json")
    try:
        return out.exists() and json.loads(sidecar.read_text()) == signature
    except (OSError, json.JSONDecodeError):
        return False


def _render_to(out: Path, signature: dict, synth: Synth, text: str, ref_file: str, ref_text: str) -> None:
    encode_opus(synth(text, ref_file, ref_text), out)
    out.with_suffix(".json").write_text(json.dumps(signature))


CURRENT_REF = RefClip("current", FALLBACK_REF[0], FALLBACK_REF[1], "narrator", 0.0, 0.0)


def _plan(passage: Passage, lib: dict, name_map: dict[str, str]) -> dict[str, tuple[str, RefClip]]:
    matched = pick(lib, passage.cluster or passage.category)
    return {
        "current": (passage.text, CURRENT_REF),
        "matched": (passage.text, matched),
        "matched_names": (apply_names(passage.text, name_map), matched),
    }


def generate(passages: list[Passage], lib: dict[str, list[RefClip]], name_map: dict[str, str], out_dir: Path,
             synth: Synth | None = None, methods: list[str] = METHODS,
             matched_temperature: float | None = None) -> dict:
    """`current` always renders as readaloud does today; the matched methods use matched_temperature."""
    out_dir.mkdir(parents=True, exist_ok=True)
    result: dict[str, dict] = {}
    for p in passages:
        result[str(p.idx)] = {}
        for method, (text, ref) in _plan(p, lib, name_map).items():
            if method not in methods:
                continue
            name = f"{p.idx:03d}-{method}.opus"
            record = {"text": text, "ref": asdict(ref)}
            temperature = None if method == "current" else matched_temperature
            signature = {"text": text, "ref_file": ref.file, "ref_text": ref.transcript}
            if temperature is not None:
                signature["temperature"] = temperature
            run = synth or functools.partial(render, temperature=temperature)
            if not _fresh(out_dir / name, signature):
                try:
                    _render_to(out_dir / name, signature, run, text, ref.file, ref.transcript)
                except TTSFailed as exc:
                    record["failed"] = str(exc)
                    print(f"passage {p.idx} {method}: FAILED {exc}", flush=True)
            if "failed" not in record:
                record["file"] = name
            result[str(p.idx)][method] = record
        print(f"passage {p.idx} done", flush=True)
    return result


def generate_names(entries: dict[str, dict], out_dir: Path, synth: Synth | None = None) -> dict[str, dict[str, str]]:
    synth = synth or render
    out_dir.mkdir(parents=True, exist_ok=True)
    out: dict[str, dict[str, str]] = {}
    for name, e in entries.items():
        # Hanzi is left out: it needs the original characters, which the source text doesn't have.
        forms = {"original": name, "respelling": e.get("respelling", "")}
        slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
        out[name] = {}
        for form, spoken in forms.items():
            if not spoken:
                continue
            file = f"name-{slug}-{form}.opus"
            sentence = f"{spoken} nodded slowly."
            signature = {"text": sentence, "ref_file": FALLBACK_REF[0], "ref_text": FALLBACK_REF[1]}
            if not _fresh(out_dir / file, signature):
                try:
                    _render_to(out_dir / file, signature, synth, sentence, *FALLBACK_REF)
                except TTSFailed as exc:
                    print(f"name {name} {form}: FAILED {exc}", flush=True)
                    continue
            out[name][form] = file
    return out
"""Chapter HTML to paragraphs, quote-level units, and TTS-sized chunks."""

import html
import re
from dataclasses import dataclass

_HEADER = re.compile(r"^\s*(Translator|Editor|Proofreader)\s*:", re.I)
_QUOTE_OPEN = "“\""
_QUOTE_CLOSE = {"“": "”", '"': '"'}

# Same order as ReadaloudTTS.TextChunker: sentence end > ;/: > comma > whitespace.
_SPLITS = [
    re.compile(r"[.!?][\"'”’)\]]*\s+"),
    re.compile(r"[;:]\s+"),
    re.compile(r",\s+"),
    re.compile(r"\s+"),
]


@dataclass
class Unit:
    idx: int
    para: int
    text: str
    quoted: bool


def html_to_paragraphs(doc: str) -> list[str]:
    text = re.sub(r"<\s*br\s*/?>|</\s*(p|div|h\d|li)\s*>", "\n", doc, flags=re.I)
    text = html.unescape(re.sub(r"<[^>]+>", "", text))
    lines = (line.strip() for line in text.split("\n"))
    return [line for line in lines if line and not _HEADER.match(line)]


def _split_para(para: str) -> list[tuple[str, bool]]:
    pieces: list[tuple[str, bool]] = []
    i = 0
    while i < len(para):
        start = min((p for p in (para.find(q, i) for q in _QUOTE_OPEN) if p >= 0), default=-1)
        if start < 0:
            pieces.append((para[i:], False))
            break
        if start > i:
            pieces.append((para[i:start], False))
        close = para.find(_QUOTE_CLOSE[para[start]], start + 1)
        end = len(para) if close < 0 else close + 1
        pieces.append((para[start:end], True))
        i = end
    return pieces


def split_units(paragraphs: list[str]) -> list[Unit]:
    units: list[Unit] = []
    for p, para in enumerate(paragraphs):
        for text, quoted in _split_para(para):
            units.append(Unit(len(units), p, text, quoted))
    return units


def _split_point(window: str) -> int | None:
    for pattern in _SPLITS:
        matches = list(pattern.finditer(window))
        if matches:
            return matches[-1].end()
    return None


def chunk(text: str, max_chars: int = 400) -> list[str]:
    remaining = text.strip()
    out: list[str] = []
    while remaining:
        if len(remaining) <= max_chars:
            out.append(remaining)
            break
        pos = _split_point(remaining[:max_chars]) or max_chars
        out.append(remaining[:pos].strip())
        remaining = remaining[pos:].strip()
    return out
"""Per-book name pronunciation: pinyin parsing, English respelling, substitution."""

import re
from functools import lru_cache

INITIALS = {
    "zh": "j", "ch": "ch", "sh": "sh", "b": "b", "p": "p", "m": "m", "f": "f", "d": "d", "t": "t",
    "n": "n", "l": "l", "g": "g", "k": "k", "h": "h", "j": "j", "q": "ch", "x": "sh", "r": "r",
    "z": "dz", "c": "ts", "s": "s",
}
FINALS = {
    "a": "ah", "o": "aw", "e": "uh", "ai": "ye", "ei": "ay", "ao": "ow", "ou": "oh", "an": "ahn",
    "en": "un", "ang": "ahng", "eng": "ung", "ong": "ong", "i": "ee", "ia": "yah", "ie": "yeh",
    "iao": "yow", "iu": "yo", "ian": "yen", "in": "een", "iang": "yahng", "ing": "ing", "iong": "yong",
    "u": "oo", "ua": "wah", "uo": "waw", "uai": "wye", "ui": "way", "uan": "wahn", "un": "wun",
    "uang": "wahng", "ue": "yweh", "ü": "yoo", "üe": "yweh", "üan": "yoo-en", "ün": "yoon",
}
# After j/q/x a written "u" is ü.
JQX_FINALS = {"u": "yoo", "ue": "weh", "uan": "wen", "un": "yoon"}
APICAL = {"zh": "r", "ch": "r", "sh": "r", "r": "r", "z": "uh", "c": "uh", "s": "uh"}
WHOLE = {
    "ya": "yah", "ye": "yeh", "yao": "yow", "you": "yoh", "yan": "yen", "yin": "yeen", "yang": "yahng",
    "ying": "ying", "yong": "yong", "yu": "yoo", "yue": "yweh", "yuan": "yoo-en", "yun": "yoon",
    "yi": "ee", "wa": "wah", "wo": "waw", "wai": "wye", "wei": "way", "wan": "wahn", "wen": "wun",
    "wang": "wahng", "weng": "wung", "wu": "woo",
    "a": "ah", "o": "aw", "e": "uh", "ai": "eye", "ei": "ay", "ao": "ow", "ou": "oh", "an": "ahn",
    "en": "un", "ang": "ahng", "eng": "ung", "er": "ar",
}


# Other English spellings to try for sounds a TTS voice may misread (default spelling first in the tables above).
FINAL_ALTS = {"e": ["ur", "uhh"], "eng": ["uhng"], "en": ["en"], "ou": ["oe"], "iu": ["yoh"], "ui": ["whey"],
              "ie": ["yeah"], "uo": ["woh"], "ian": ["yan"], "in": ["in"], "ai": ["igh"], "ang": ["ung"]}
WHOLE_ALTS = {"er": ["er", "arr"], "e": ["ur"], "you": ["yo"], "yi": ["yee"], "ai": ["i"], "en": ["en"]}
APICAL_ALTS = {"r": ["ruh"], "uh": ["z"]}


def _syllable_options(syl: str) -> list[str]:
    """Spellings for one pinyin syllable: the default respelling first, then alternatives."""
    base = _respell_syllable(syl)
    if base is None:
        return []
    if syl in WHOLE:
        alts = WHOLE_ALTS.get(syl, [])
    else:
        ini = next(i for i in sorted(INITIALS, key=len, reverse=True) if syl.startswith(i))
        fin = syl[len(ini):]
        if fin == "i" and ini in APICAL:
            alts = [INITIALS[ini] + a for a in APICAL_ALTS[APICAL[ini]]]
        elif ini in ("j", "q", "x") and fin in JQX_FINALS:
            alts = []
        else:
            alts = [INITIALS[ini] + a for a in FINAL_ALTS.get(fin, [])]
    return [base] + [a for a in alts if a != base]


def _respell_syllable(syl: str) -> str | None:
    if syl in WHOLE:
        return WHOLE[syl]
    for ini in sorted(INITIALS, key=len, reverse=True):
        if syl.startswith(ini):
            fin = syl[len(ini):]
            if fin == "i" and ini in APICAL:
                return INITIALS[ini] + APICAL[ini]
            if ini in ("j", "q", "x") and fin in JQX_FINALS:
                return INITIALS[ini] + JQX_FINALS[fin]
            if fin in FINALS:
                return INITIALS[ini] + FINALS[fin]
            return None
    return None


@lru_cache(maxsize=None)
def _parse_word(word: str) -> tuple[str, ...] | None:
    if not word:
        return ()
    for n in range(min(6, len(word)), 0, -1):
        head = word[:n]
        if _respell_syllable(head) is not None:
            rest = _parse_word(word[n:])
            if rest is not None:
                return (head,) + rest
    return None


def _words(name: str) -> list[str]:
    return name.lower().replace("v", "ü").split()


def syllables(name: str) -> list[str] | None:
    out: list[str] = []
    for word in _words(name):
        parsed = _parse_word(word)
        if parsed is None:
            return None
        out.extend(parsed)
    return out or None


def respell(name: str) -> str | None:
    words = []
    for word in _words(name):
        parsed = _parse_word(word)
        if parsed is None:
            return None
        spelled = "".join(_respell_syllable(s) for s in parsed)
        words.append(spelled[0].upper() + spelled[1:])
    return " ".join(words) or None


def _cap(word: str) -> str:
    return word[0].upper() + word[1:]


def _options(name: str) -> list[list[list[str]]] | None:
    words = [_parse_word(w) for w in _words(name)]
    if not words or any(w is None for w in words):
        return None
    return [[_syllable_options(s) for s in w] for w in words]


def _spell(choice: list[list[str]]) -> str:
    return " ".join(_cap("".join(w)) for w in choice)


def respell_variants(name: str) -> list[str]:
    """The default respelling, then the same with one syllable at a time swapped for an alternative."""
    options = _options(name)
    if options is None:
        return []
    base = [[o[0] for o in w] for w in options]
    out = [_spell(base)]
    for wi, w in enumerate(options):
        for si, opts in enumerate(w):
            for alt in opts[1:]:
                choice = [list(x) for x in base]
                choice[wi][si] = alt
                if _spell(choice) not in out:
                    out.append(_spell(choice))
    return out


def combine_best(name: str, scores: dict[str, float]) -> str:
    """Per syllable, keep the alternative whose one-syllable variant scored best (ties keep the default)."""
    options = _options(name)
    base = [[o[0] for o in w] for w in options]
    base_score = scores.get(_spell(base), 0.0)
    chosen = [list(x) for x in base]
    for wi, w in enumerate(options):
        for si, opts in enumerate(w):
            best, best_score = opts[0], base_score
            for alt in opts[1:]:
                trial = [list(x) for x in base]
                trial[wi][si] = alt
                if scores.get(_spell(trial), -1.0) > best_score:
                    best, best_score = alt, scores[_spell(trial)]
            chosen[wi][si] = best
    return _spell(chosen)


"""Reference clip candidates, screening helpers, and the per-category library."""

import json
import re
from dataclasses import asdict, dataclass
from difflib import SequenceMatcher
from pathlib import Path

import numpy as np

from .bonsai import Tag
from .config import FALLBACK_REF

MIN_S, MAX_S = 6.0, 15.0
MAX_GAP_S = 1.0
SILENCE_DBFS = -45.0
FRAME_S = 0.02


@dataclass
class Candidate:
    category: str
    speaker: str
    start: float
    end: float
    text: str


@dataclass
class RefClip:
    category: str
    file: str
    transcript: str
    speaker: str
    start: float
    end: float
    score: float = 0.0
    fallback: bool = False


def category_of(tag: Tag) -> str | None:
    strong = tag.mood in ("intense", "action")
    if tag.kind == "narration":
        return "narration_action" if strong else "narration_calm"
    if tag.sex == "female":
        return "female_intense" if strong else "female_calm"
    if tag.sex == "male":
        return "male_intense" if strong else "male_casual"
    return None


def _category_key(seg: dict) -> tuple[str, str] | None:
    cat = category_of(Tag(**seg["tag"]))
    return None if cat is None else (cat, seg["tag"]["speaker"])


def candidates(tagged: list[dict], key=_category_key) -> list[Candidate]:
    """Merge contiguous segments sharing key(seg) = (category, speaker) into 6–15 s spans."""
    out: list[Candidate] = []
    run: list[dict] = []
    run_key = None

    def flush():
        if run and run[-1]["end"] - run[0]["start"] >= MIN_S:
            out.append(Candidate(run_key[0], run_key[1], run[0]["start"], run[-1]["end"],
                                 " ".join(s["text"] for s in run)))

    for seg in tagged:
        seg_key = key(seg)
        contiguous = run and seg["start"] - run[-1]["end"] < MAX_GAP_S
        fits = run and seg["end"] - run[0]["start"] <= MAX_S
        if seg_key is not None and seg_key == run_key and contiguous and fits:
            run.append(seg)
            continue
        flush()
        run, run_key = ([seg], seg_key) if seg_key is not None else ([], None)
    flush()
    return out


