import io
import json
import os
import signal

import httpx
import pytest
from PIL import Image

from svc import edits, scan, sheets, tagger
from svc.bonsai import BonsaiClient


@pytest.fixture
def cfg(settings, tmp_path):
    return settings.model_copy(
        update={"settle_seconds": 0, "export_path": tmp_path / "mega/edits.json"}
    )


class Fake:
    """A fake Bonsai server; `reply` maps the request's JSON body to the model's content."""

    def __init__(self, reply=None):
        self.requests: list[dict] = []
        self.reply = reply or (lambda body: {"tags": ["Slime", "green"], "description": "A slime."})
        self.healthy = True
        self.down = False
        self.finish = "stop"

    def __call__(self, request: httpx.Request) -> httpx.Response:
        if request.url.path == "/health":
            return httpx.Response(200 if self.healthy else 503, json={"status": "ok"})
        if self.down:
            raise httpx.ConnectError("connection refused")
        body = json.loads(request.content)
        self.requests.append(body)
        out = self.reply(body)
        content = out if isinstance(out, str) else json.dumps(out)
        return httpx.Response(
            200,
            json={"choices": [{"message": {"content": content}, "finish_reason": self.finish}]},
        )

    def client(self):
        return BonsaiClient("http://bonsai", transport=httpx.MockTransport(self))


class Sys:
    def __init__(self):
        self.calls: list[list[str]] = []

    def __call__(self, args):
        self.calls.append(list(args))
        return ""


def _go(conn, cfg, fake, guard=lambda: False, **kw):
    sysd = kw.pop("systemctl", Sys())
    posted = []
    stats = tagger.run(
        conn,
        cfg,
        client=fake.client(),
        guard=guard,
        systemctl=sysd,
        notify=lambda: posted.append(1),
        sleep=lambda s: None,
        **kw,
    )
    return stats, sysd, posted


def _scan(conn, cfg):
    scan.scan(conn, cfg)


def _png(path, size, color=(200, 50, 50, 255)):
    path.parent.mkdir(parents=True, exist_ok=True)
    Image.new("RGBA", size, color).save(path)


def _content(conn, path):
    return conn.execute(
        "SELECT c.* FROM contents c JOIN assets a USING (sha256) WHERE a.path = ?", (path,)
    ).fetchone()


def test_tags_copied_to_siblings_and_copies(conn, cfg, lib_root):
    _png(lib_root / "Sprites/Props/PackD/16x16/Props/chest.png", (80, 80))
    _png(lib_root / "Sprites/Props/PackD/32x32/Props/chest.png", (160, 160))
    _png(lib_root / "Sprites/Props/PackE/chest_copy.png", (80, 80))  # same bytes as the 16x16
    _scan(conn, cfg)
    fake = Fake()
    stats, sysd, posted = _go(conn, cfg, fake)
    rows = conn.execute(
        "SELECT a.path, c.model_tags, c.model_at FROM assets a JOIN contents c USING (sha256)"
        " WHERE a.path LIKE '%chest%'"
    ).fetchall()
    assert len(rows) == 3
    assert all(json.loads(r["model_tags"]) == ["slime", "green"] for r in rows)
    assert all(r["model_at"] for r in rows)
    chest_calls = [
        r for r in fake.requests if "chest" in json.dumps(r["messages"][0]["content"][0]["text"])
    ]
    assert len(chest_calls) == 1
    assert posted == [1]
    assert sysd.calls[-1][:2] == ["stop", cfg.bonsai_unit]

        leads.append(stats.done)
    assert all(leads) and sum(leads) > 0
    assert tagger.build_jobs(conn) == []


def test_empty_queue_never_starts_bonsai(conn, cfg, lib_root):
    _scan(conn, cfg)
    _go(conn, cfg, Fake(lambda b: {"tags": ["x"], "description": "d"}))
    stats, sysd, posted = _go(conn, cfg, Fake(lambda b: {"tags": ["x"], "description": "d"}))
    assert (stats.done, stats.status) == (0, "done")
    assert sysd.calls == [] and posted == []
# Pytest suite for gameassets, exposed as the `gameassets-tests` flake
# check so `nix flake check` runs it.
#
# Not a buildPythonPackage: the service runs from the source tree in the
# nix store, so there is no wheel to build.
{
  runCommand,
  python3,
  nodejs,
  lib,
}:
let
  pythonEnv = import ./python.nix { inherit python3; };
  src = lib.cleanSourceWith {
    src = ./.;
    filter =
      path: _type:
      !(builtins.elem (baseNameOf path) [
        "__pycache__"
        ".pytest_cache"
      ]);
  };
in
# nodejs: test_web.py checks that web/app.js parses (skipped without node).
runCommand "gameassets-tests"
  {
    nativeBuildInputs = [
      pythonEnv
      nodejs
    ];
  }
  ''
    cp -r ${src}/. .
    chmod -R +w .
    pytest -q -p no:cacheprovider
    touch $out
  ''

